// CSD_RATIONALE_BEGIN
// Strategy: GenerateWithPrefixAndManagedSpan at 72% prefix budget, up from 78%
// in the best known result (attempt 24: 34.7% accuracy, 79.6% syntax).
//
// Diagnosis from attempt 29 (hand-written loop, 53.1% syntax):
//   - 12 unterminated spans: model opened << then EOS or dead-end before >>
//   - 10 missing spans: model never wrote << (hit maxSteps without constrained activity)
//   - GenerateWithPrefixAndManagedSpan (attempt 24) fixes the missing-span failure
//     by forcing << at prefixBudget, but 78% prefix left only 198 steps for the
//     constrained span; reducing to 72% gives 252 steps, reducing unterminated spans.
//
// Changes vs best (attempt 24):
//   1. prefixBudget: 78% → 72% (648/900 vs 702/900), giving 252 vs 198 constrained steps.
//      This directly addresses the unterminated-span failure cluster.
//   2. boostAmount: 8.0 → 10.0, pushing constrained-valid tokens harder during span fill.
//   3. Guidance: removed specific variable-name examples (model was copying them literally
//      and producing syntactically valid but semantically wrong expressions); kept the
//      format description and int() requirement.
//   4. narrowThreshold: 6 (unchanged from attempt 24).
//
// Attempt 27 showed that raising prefixBudget to 85% regressed accuracy by 4pp;
// this attempt goes in the other direction (more span budget), which should raise
// syntax rate and, by enabling more complete expressions, accuracy as well.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Branch A (maxSteps == 0): We assign insideConstrainedOut := insideConstrained and
//   currentConstrainedOut := currentConstrained. The method preconditions directly supply
//   insideConstrained ==> parser.IsValidPrefix(currentConstrained) and
//   !insideConstrained ==> currentConstrained == [], so the invariant holds trivially.
//
//   Branch B (maxSteps > 0): GenerateWithPrefixAndManagedSpan's postcondition explicitly
//   guarantees !insideConstrainedOut ==> currentConstrainedOut == [] and
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). We assign the
//   outputs directly from the helper, so no additional branch can violate the invariant.
//   Inside the helper, constrained tokens are chosen via AdaptiveConstrainedStep, which
//   hard-masks to parser-valid tokens, and the span is closed only when IsCompletePrefix holds.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps (steps = cost = maxSteps here)
//
//   Branch A (maxSteps == 0): generated = generatedPrefix, cost = 0. |generated| = |generatedPrefix|
//   + 0 <= |generatedPrefix| + 0. ✓
//
//   Branch B (maxSteps > 0): GenerateWithPrefixAndManagedSpan's postcondition guarantees
//   |generated| <= |generatedPrefix| + maxSteps. cost is set to maxSteps, satisfying cost <= maxSteps.
//   Each token appended to generated (whether in free phase or inside the constrained span) consumes
//   exactly one step. EOS tokens and any rejected suffix tokens from constrained steps also consume
//   one step without increasing |generated|, so visible growth is always ≤ budget consumed.
//   Liveness: maxSteps > 0 ==> cost = maxSteps > 0. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  // No budget; return inputs unchanged with cost := 0
} else {
  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. At the very end, write your answer as <<expr>> " +
    "where expr uses only: variable names (no curly braces), integers, +, -, *, /, //, %, (, ), int(). " +
    "ALWAYS wrap integer results in int(). No LaTeX, no {braces}, no ** operator. " +
    "Keep the expression short. One <<expr>> at the very end only.");

  var prefixBudget: nat := (maxSteps * 72) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt,
    generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget,
    validTokenGroups,
    10.0,
    6,
    eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}

